    address public runner;
    mapping(uint256 => uint256) public worders;
    mapping(uint256 => uint256) public sendids;

    event CREATE(
        address indexed account,
        uint256 ratio,
        uint256 amount,
        uint256 times
    );
    event SENDREWARD(
        address indexed account,
        uint256 id,
        uint256 amount,
        uint256 times
    );
    event WITHDRAW(
        address indexed account,
        uint256 id,
        uint256 amount,
        uint256 times
    );

    event XPGXDf77(
        address indexed account,
        address indexed taccount,
        uint256 id,
        uint256 amount,
        uint256 times
    );

    constructor() {
        runner = _msgSender();
        setSigner(_msgSender(), true);
    }

    modifier onlyRunner() {
        require(_msgSender() == runner, "!runner");
        _;
    }

    function setRunner(address _runner) external onlyOwner {
        runner = _runner;
    }

    function vly5ChOkLkQk4u(
